user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "EXPLAINS_OBSERVED_ANOMALY",
    "definition": "The reasoning accounts causally for why a recorded observation produced an unexpected, empty, or puzzling result, naming a concrete mechanism (tool/option semantics, symlink handling, process lifecycle) instead of treating the result as a failure of the underlying goal.",
    "parameters": [
      {
        "name": "explanation",
        "type": "reasoning",
        "description": "The agent text that accounts for the puzzling result."
      },
      {
        "name": "anomalous_observation",
        "type": "observation",
        "description": "The observation whose output was empty, missing, or contrary to expectation."
      }
    ],
    "assertion_conditions": [
      "The explanation explicitly refers to a result contained in the observation that deviated from expectation or left a property undetermined.",
      "The explanation identifies a concrete cause for that result (e.g., a command not following symlinks, a shell lacking a numeric conversion function, a non-reaping parent process)."
    ],
    "exclusion_conditions": [
      "The reasoning merely restates or quotes the observation without a causal account.",
      "The reasoning only proposes the next action and gives no cause for the puzzling result.",
      "The referenced result is not present in the observation (no traceable link between the two nodes)."
    ]
  },
  {
    "name": "REVERIFIES_WITH_ALTERNATIVE_MECHANISM",
    "definition": "A prior observation left a system property undetermined or contradicted expectation, and the action re-establishes that same property through a different tool, option, or access path rather than repeating the original check.",
    "parameters": [
      {
        "name": "recheck_action",
        "type": "action",
        "description": "The action performing the alternative re-verification."
      },
      {
        "name": "inconclusive_observation",
        "type": "observation",
        "description": "The earlier check whose output was empty, ambiguous, or insufficient to settle the property."
      }
    ],
    "assertion_conditions": [
      "The prior observation failed to reveal a property that the agent expected or needed to know.",
      "The action inspects the same system property using a different command, option, or access path than the earlier check.",
      "The differing technique is what makes the property observable."
    ],
    "exclusion_conditions": [
      "The action reruns the identical command with identical options, adding no new observability.",
      "The action inspects a different property than the one left undetermined.",
      "The earlier observation was conclusive, so the action is routine verification rather than alternative re-verification."
    ]
  },
  {
    "name": "RESOLVES_FUNCTIONAL_DOUBT_BY_PROBE",
    "definition": "The reasoning raises doubt about whether an observed anomaly actually impairs a required capability, a probe action exercises exactly that capability, and the resulting observation demonstrates the capability still works, allowing the anomaly to be dismissed.",
    "parameters": [
      {
        "name": "doubt_reasoning",
        "type": "reasoning",
        "description": "The agent text expressing uncertainty about whether the anomaly breaks functionality."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action that exercises the capability put in doubt."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the outcome of the probe."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies an observed anomaly and questions whether it affects a required capability.",
      "The probe action directly exercises the capability that was questioned.",
      "The probe result shows the capability behaving successfully, providing grounds to treat the anomaly as harmless."
    ],
    "exclusion_conditions": [
      "The probe does not target the capability that was questioned.",
      "The probe result is failing, inconclusive, or unrelated to the doubt.",
      "No doubt about functionality is expressed; the probe is ordinary acceptance testing."
    ]
  },
  {
    "name": "RESTORES_PRISTINE_STATE",
    "definition": "The action removes data, deployments, and credentials created during verification and resets configuration so that the environment returns to its documented initial state before the end user performs their own workflow.",
    "parameters": [
      {
        "name": "cleanup_action",
        "type": "action",
        "description": "The action that deletes verification artifacts and resets state."
      }
    ],
    "assertion_conditions": [
      "The action deletes or resets artifacts produced by earlier testing (repository refs/objects/index, deployed web content, temporary keys, temporary directories).",
      "The action restores a documented starting configuration (e.g., empty repository with a default HEAD, empty web root, empty authentication file) rather than adding new capability.",
      "The effect is removal or reset, not installation or configuration of new functionality."
    ],
    "exclusion_conditions": [
      "The action only inspects state without changing it.",
      "The action installs, configures, or extends functionality.",
      "The action removes scratch files unrelated to returning the environment to its documented initial state."
    ]
  },
  {
    "name": "VERIFIES_ENUMERATED_STATE_ITEMS",
    "definition": "The reasoning itemizes discrete facets of system state to be confirmed, and the action performs a read-only inspection that reads back those same facets in one pass.",
    "parameters": [
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The read-only action that reads back the enumerated state facets."
      },
      {
        "name": "checklist_reasoning",
        "type": "reasoning",
        "description": "The agent text enumerating the specific facets to be confirmed."
      }
    ],
    "assertion_conditions": [
      "The reasoning lists multiple discrete facets to confirm (services, listening ports, ownership/permissions, repository refs, configuration contents, HTTP status).",
      "The action issues read-only commands covering those same facets.",
      "The facets checked by the action can be mapped onto the enumerated items."
    ],
    "exclusion_conditions": [
      "The action mutates state rather than reading it back.",
      "The action checks facets that were not enumerated, or the reasoning gives only a general goal without itemized facets.",
      "The reasoning enumerates items but the action addresses only one of them."
    ]
  },
  {
    "name": "PROVISIONS_DISPOSABLE_CREDENTIAL",
    "definition": "The action creates transient authentication material in a temporary location and installs it into the authentication path solely so that the login or authentication flow can be exercised during testing, without intending it as the end user's credential.",
    "parameters": [
      {
        "name": "provisioning_action",
        "type": "action",
        "description": "The action generating and installing the temporary credential."
      }
    ],
    "assertion_conditions": [
      "The action generates authentication material (key pair, token) at a temporary path.",
      "The generated material is placed into the authentication path (e.g., an authorized-keys file) so that a test login can succeed.",
      "The material is distinct from the credential the end user is expected to configure."
    ],
    "exclusion_conditions": [
      "The action sets up the credential the end user will keep and use.",
      "The action only reads or inspects existing credentials without generating new material.",
      "Generated material is intended for permanent production use rather than a test of the authentication path."
    ]
  },
  {
    "name": "REPLICATES_DOCUMENTED_USER_COMMANDS",
    "definition": "The reasoning lays out the exact command sequence the requester is expected to run, and the action executes that sequence verbatim against the configured system in a fresh working location as an acceptance replay.",
    "parameters": [
      {
        "name": "replay_action",
        "type": "action",
        "description": "The action executing the documented command sequence."
      },
      {
        "name": "sequence_reasoning",
        "type": "reasoning",
        "description": "The agent text enumerating the expected command sequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning enumerates the specific commands the requester will run, in order.",
      "The action executes those same commands, in the same order, rather than ad-hoc equivalents.",
      "The execution occurs in a clean location so the result reflects the requester's starting conditions."
    ],
    "exclusion_conditions": [
      "The action uses substitute commands that only approximate the documented workflow.",
      "The reasoning states general verification goals without listing a concrete command sequence.",
      "The action executes only a fragment of the documented sequence."
    ]
  },
  {
    "name": "INSTALLS_STARTUP_HOOK",
    "definition": "The action modifies shell startup configuration so that a previously created helper is invoked automatically on future interactive or login shells, wiring the helper into the session lifecycle.",
    "parameters": [
      {
        "name": "hook_action",
        "type": "action",
        "description": "The action writing or appending the helper invocation into startup files."
      }
    ],
    "assertion_conditions": [
      "The action writes to shell startup configuration (profile directories or shell rc files).",
      "The written content invokes a named helper (e.g., a script path) so it runs on subsequent shells.",
      "The invocation is written in a failure-tolerant form that does not disturb the session."
    ],
    "exclusion_conditions": [
      "The action only creates the helper file without wiring it into startup configuration.",
      "The startup file is edited for unrelated purposes (environment variables, aliases, PATH) with no helper invocation.",
      "The invocation is written into a one-off command rather than persistent startup configuration."
    ]
  },
  {
    "name": "REUSES_ARTIFACT_CREATED_BY_EARLIER_ACTION",
    "definition": "An artifact (file, credential, directory) produced by one action is consumed as an operational input by a later action, creating a traceable cross-action dependency on that produced value.",
    "parameters": [
      {
        "name": "consumer_action",
        "type": "action",
        "description": "The later action whose command references the produced artifact."
      },
      {
        "name": "producer_action",
        "type": "action",
        "description": "The earlier action that created the artifact."
      }
    ],
    "assertion_conditions": [
      "The producer action creates a file, credential, or path at a specific location.",
      "The consumer action's command references that same location as an input (e.g., a key path, a generated script path).",
      "The producer precedes the consumer, and no other node supplies the artifact."
    ],
    "exclusion_conditions": [
      "Both actions merely reference an artifact that pre-existed and was not created by the producer.",
      "The consumer action mentions the path only in narration without using it operationally.",
      "The artifact was created by an action outside the compared pair."
    ]
  },
  {
    "name": "CONFIRMS_DEPLOYMENT_PIPELINE",
    "definition": "A publishing action successfully writes content into the configured storage path, and a subsequent retrieval action reads that content back through the serving path, with the result showing the published content is being served.",
    "parameters": [
      {
        "name": "publish_action",
        "type": "action",
        "description": "The action that commits/pushes/installs content into the repository or deployment source."
      },
      {
        "name": "retrieval_action",
        "type": "action",
        "description": "The action that fetches the content through the serving endpoint."
      },
      {
        "name": "served_result",
        "type": "observation",
        "description": "The observation reporting the retrieved content and server response."
      }
    ],
    "assertion_conditions": [
      "The publishing action reports success in writing the content to the deployment source.",
      "The retrieval action addresses the serving endpoint that is supposed to expose that content after deployment.",
      "The served result contains the published content with a success status, showing the publish-to-serve path works end to end."
    ],
    "exclusion_conditions": [
      "The retrieval occurs before the publishing action succeeds, so the served result cannot stem from that deployment.",
      "The served content differs from what was published.",
      "The retrieval reads a local copy or the repository directly rather than the serving endpoint."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_EXECUTION_PLAN",
    "definition": "The reasoning explicitly expresses an intended future action or ordered sequence of actions that the agent intends to perform next in service of the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action(s) or the plan to be carried out."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly names at least one action that is still to be performed (e.g., inspecting a file, listing a workspace, compiling an artifact, verifying a result).",
      "The intended action is presented as the agent's own next step, not as a hypothetical or rejected alternative."
    ],
    "exclusion_conditions": [
      "Merely reporting actions that have already been completed does not constitute a plan.",
      "Restating the user's task requirements without committing to a next action is not a plan.",
      "Post-hoc summarization of finished work is not a plan."
    ]
  },
  {
    "name": "IDENTIFIES_DEFECT_IN_OBSERVED_CONTENT",
    "definition": "The reasoning analyzes the content returned by an observation and pinpoints a concrete deficiency in that content that must be corrected for the task to succeed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text performing the analysis and naming the deficiency."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier observation whose returned content contains the deficient artifact."
      }
    ],
    "assertion_conditions": [
      "The observation returns the actual content of an artifact (e.g., source text of a file) rather than mere metadata.",
      "The reasoning names specific missing, incomplete, or erroneous portions of that content (e.g., unresolved holes, absent steps, absent branches), rather than describing the content in general terms."
    ],
    "exclusion_conditions": [
      "The reasoning only restates or quotes the observed content without locating a deficiency.",
      "The reasoning discusses the artifact without any content from an observation having been supplied.",
      "The observation reports a tool failure rather than artifact content."
    ]
  },
  {
    "name": "GUIDES_ACTION_CONTENT",
    "definition": "The reasoning specifies the concrete content or form of an operation that a subsequent action then carries out, so that the action's payload is traceable to the reasoning.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that decides what the operation should do or which content it should supply."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The action that performs the operation whose content corresponds to the reasoning."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a concrete intended operation or the concrete content to be produced (e.g., the exact replacement text, the exact command form).",
      "The action's payload matches that stated intent in substance, not merely in topic.",
      "The reasoning precedes the action."
    ],
    "exclusion_conditions": [
      "The reasoning only expresses a general goal while the action's content is fixed by a prior observation or by chance.",
      "The action diverges from what the reasoning specified.",
      "The reasoning is written after the action and only reports it."
    ]
  },
  {
    "name": "REPLACES_DEFECTIVE_CONTENT_OBSERVED",
    "definition": "A modification action rewrites the very resource whose deficient content was reported by an earlier observation, supplying content that fills the identified gap.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The modification action that writes or edits the resource."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier observation that returned the deficient content of that same resource."
      }
    ],
    "assertion_conditions": [
      "The observation returns content of a specific named resource (e.g., a file path) that lacks required elements.",
      "The action targets that same resource and supplies the content that was missing, replacing the deficient portion.",
      "The action precedes any confirmation of the resource's corrected state."
    ],
    "exclusion_conditions": [
      "The action targets a different resource than the one observed.",
      "The action is read-only or only inspects the resource.",
      "The observation is unrelated to the resource being written."
    ]
  },
  {
    "name": "CHECKS_TOOL_AVAILABILITY",
    "definition": "The action queries whether a required tool or toolchain executable is present and usable, as a precondition check before performing the primary task.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action invoking a presence or version query on the required tool."
      }
    ],
    "assertion_conditions": [
      "The invocation resolves the location of the executable or asks the tool for its version, rather than performing the primary task.",
      "The stated intent or surrounding reasoning links the check to a tool needed for the primary task."
    ],
    "exclusion_conditions": [
      "The action performs the primary task itself (e.g., running the compiler on the target artifact).",
      "The action queries an unrelated utility or an unrelated property of the environment."
    ]
  },
  {
    "name": "PERFORMS_PRIMARY_BUILD",
    "definition": "The action executes the build or compilation step on the target artifact as the main operation of the task, rather than checking prerequisites or inspecting outputs.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action running the build/compilation command on the target artifact."
      }
    ],
    "assertion_conditions": [
      "The command invokes the build tool on the target artifact path.",
      "The command optionally combines the build with listing of produced outputs in the same invocation."
    ],
    "exclusion_conditions": [
      "The action only queries tool availability or version.",
      "The action only loads or prints an already compiled artifact for inspection.",
      "The action only reads source text without building."
    ]
  },
  {
    "name": "INDICATES_SUCCESSFUL_BUILD_WITH_ARTIFACT",
    "definition": "The observation resulting from a build or compilation command provides evidence that the build succeeded and that the compiled output artifact was produced.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation returning the build command's output."
      }
    ],
    "assertion_conditions": [
      "The observation is the result of a build/compilation invocation.",
      "The output contains no error indication and evidences the compiled output artifact, such as by listing it or a success marker."
    ],
    "exclusion_conditions": [
      "The output contains compiler errors or a nonzero exit indication.",
      "The output merely lists files without any build having been executed.",
      "The output comes from a verification or inspection command rather than a build."
    ]
  },
  {
    "name": "IS_INVOCATION_ERROR_OBSERVATION",
    "definition": "The observation reports an error caused by the malformed or misinterpreted form of the tool invocation, rather than by a defect in the artifact being processed.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation returning the failing tool output."
      }
    ],
    "assertion_conditions": [
      "The observation is marked as an error or shows a nonzero exit.",
      "The error message describes the tool's inability to interpret or locate something according to its argument convention (e.g., it looked for a file name derived from the supplied argument)."
    ],
    "exclusion_conditions": [
      "The error indicates that the processed artifact itself is invalid or failed verification.",
      "The error reports an unavailable required tool or missing dependency.",
      "The observation reports success."
    ]
  },
  {
    "name": "CORRECTS_FAILED_INVOCATION",
    "definition": "A retry action pursues the same verification or inspection goal as a failed invocation while changing precisely the aspect of the invocation that the error identified.",
    "parameters": [
      {
        "name": "retry_action",
        "type": "action",
        "description": "The action that re-attempts the operation after the failure."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The earlier observation reporting the invocation error."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the retry action, and the retry action targets the same overall goal.",
      "The retry action's parameters differ from the failed invocation in exactly the respect the error message indicated.",
      "The retry preserves the underlying resource being inspected or verified."
    ],
    "exclusion_conditions": [
      "The retry repeats the identical invocation that already failed.",
      "The action abandons the goal and does something unrelated.",
      "The action changes the artifact rather than the invocation form."
    ]
  },
  {
    "name": "CONFIRMS_CORRECTED_VERIFICATION",
    "definition": "A retry action addresses a specific invocation failure, and a later observation establishes that the intended verification result was obtained.",
    "parameters": [
      {
        "name": "retry_action",
        "type": "action",
        "description": "The action attempting to fix the failed invocation."
      },
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The earlier observation reporting the invocation failure."
      },
      {
        "name": "confirmation_observation",
        "type": "observation",
        "description": "The later observation showing the intended verification output."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the retry action, and the retry action corrects the identified invocation problem.",
      "The confirmation observation follows the retry action and contains the sought result (e.g., the queried declaration printed with its full content) without error."
    ],
    "exclusion_conditions": [
      "The retry is performed without any later observation demonstrating the sought result.",
      "The later observation still reports an error or an empty/irrelevant result.",
      "The later observation confirms something other than the failure's subject."
    ]
  },
  {
    "name": "ATTEMPTS_ARTIFACT_CONTENT_VERIFICATION",
    "definition": "The action attempts to inspect the semantic content of an already produced compiled artifact by loading it or querying a declaration from it, rather than by rebuilding it or reading raw bytes.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action that attempts to load the compiled artifact or query a declaration from it."
      }
    ],
    "assertion_conditions": [
      "The invocation attempts to load a compiled artifact into the tool's environment or asks the tool to print/check a named declaration.",
      "The action is distinct from the build that produced the artifact and from file-listing or byte-level inspection."
    ],
    "exclusion_conditions": [
      "The action rebuilds the artifact from source.",
      "The action only lists files or checks file sizes/timestamps.",
      "The action reads source text instead of the compiled artifact."
    ]
  },
  {
    "name": "ASSERTS_TASK_COMPLETION_WITH_EVIDENCE",
    "definition": "The reasoning declares the overall task finished and backs the claim by citing the concrete artifacts produced and the verifications performed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text concluding the task and citing its supporting evidence."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly states that the task is complete or that all required steps are done.",
      "It references the concrete produced artifacts and the checks that were run to establish success."
    ],
    "exclusion_conditions": [
      "The reasoning describes an intermediate step or an open problem rather than final completion.",
      "The claim of completion cites no produced artifact or verification result.",
      "The reasoning admits that a required verification is still missing or failing."
    ]
  },
  {
    "name": "ANTICIPATES_FAILURE_MODE",
    "definition": "The reasoning predicts a specific failure mechanism that a default or naive configuration would produce, and explains how that mechanism leads to the failure, before any such failure has been observed.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text predicting a concrete failure mechanism and its consequence."
      }
    ],
    "assertion_conditions": [
      "The reasoning names a concrete failure mode that could arise from a default or naive setup, such as an account locked for key authentication, a commit finding no changes to record, stale deployed content preventing a later push, or a service unable to start without a supervisor.",
      "The reasoning explains the causal mechanism by which the default behavior produces that failure.",
      "The prediction is made before any observation in the trajectory reports that failure."
    ],
    "exclusion_conditions": [
      "The text reacts to a failure that has already been observed in a tool result.",
      "The text offers only generic caution or best-practice advice without identifying a specific failure mechanism.",
      "The text predicts a failure that is unrelated to the configuration being implemented."
    ]
  },
  {
    "name": "DERIVES_ENVIRONMENT_CONSTRAINT",
    "definition": "The reasoning interprets the content of a prior observation to establish a capability, absence, or structural constraint of the environment that conditions the chosen approach.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text drawing a capability or constraint conclusion from observed environment state."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier tool result whose content supplies the environment facts being interpreted."
      }
    ],
    "assertion_conditions": [
      "The reasoning states at least one specific environment fact that is traceable to the content of the observation, such as available or missing tools, package-manager reachability, process supervision model, user accounts, or filesystem layout.",
      "The reasoning treats that fact as a constraint or enabler that affects how the agent proceeds."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or paraphrases the raw observation without drawing a constraint or capability conclusion.",
      "The observation only confirms that a command ran successfully and supplies no environment fact.",
      "The nodes are merely temporally adjacent or topically similar."
    ]
  },
  {
    "name": "ALIGNS_PROVISIONED_NAMES_WITH_REQUEST",
    "definition": "The action creates or registers a named resource such as an account, filesystem path, hostname mapping, or listening endpoint under the exact identifier that the requester's unmodified commands will address, so those commands resolve to the provisioned resource.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The provisioning action that establishes a named resource and fixes its identifier."
      }
    ],
    "assertion_conditions": [
      "The action establishes a named resource such as a user account, repository path, local hostname entry, or service listening endpoint.",
      "The identifier chosen in the action equals the identifier appearing in the requester's commands, such as an account name, repository path, host alias, or port number."
    ],
    "exclusion_conditions": [
      "The resource is created under an arbitrary or default identifier unrelated to the requester's commands.",
      "The chosen identifier differs from the requested one or would require the requester to alter the commands.",
      "The action only installs or inspects software without fixing the name of a resource."
    ]
  },
  {
    "name": "INSTALLS_MISSING_DEPENDENCIES",
    "definition": "The action installs software packages that provide capabilities which the reasoning had identified as absent from the environment, and the installation occurs before the first attempt to use those capabilities.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The package installation action supplying the absent capabilities."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that identified the specific capabilities as missing."
      }
    ],
    "assertion_conditions": [
      "The reasoning records specific tools or services as absent or unusable in the environment.",
      "The action installs packages that provide those tools or services.",
      "The installation occurs before any action that depends on them."
    ],
    "exclusion_conditions": [
      "Packages are installed without any preceding identification of a gap.",
      "The gap is identified but no installation is attempted within the window.",
      "The action only refreshes or inspects package metadata without installing."
    ]
  },
  {
    "name": "MITIGATES_ANTICIPATED_PITFALL",
    "definition": "The action applies a concrete countermeasure, visible in its own arguments, that prevents a specific failure mechanism the reasoning had predicted for a default or naive configuration.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action whose arguments contain the countermeasure."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The earlier agent text predicting the failure mechanism that the countermeasure addresses."
      }
    ],
    "assertion_conditions": [
      "The reasoning predicts a specific failure mechanism for the default or naive configuration.",
      "The action contains an explicit flag, option, marker, permission setting, configuration directive, or resolution entry that directly prevents that mechanism.",
      "The correspondence between the countermeasure and the predicted mechanism is traceable by content, not merely by topic or proximity."
